import{z as B,x as A,o as l,c as s,q as r,j as n,D as e,d as t,s as o,S as p,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"条件要素需求","description":"","frontmatter":{"title":"条件要素需求","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/conditional-factor-demand.md","filePath":"econ/conditional-factor-demand.md","lastUpdated":1791063341000}'),d={name:"econ/conditional-factor-demand.md"};function q(h,a,c,m,w,D){const i=A("Mermaid");return l(),s("div",null,[a[2]||(a[2]=r('<h1 id="条件要素需求" tabindex="-1">条件要素需求 <a class="header-anchor" href="#条件要素需求" aria-label="Permalink to &quot;条件要素需求&quot;">​</a></h1><div class="epigraph"><p>锁住产量时要素如何随工资替换，与放开产量后要素如何随工资、产品价格一起动，是两条曲线——前者没有产出效应。</p><footer>—— 据 Varian, Microeconomic Analysis；对照 Shephard 与 Hotelling 引理</footer></div><p><a href="/econ/shephard-hotelling">上一课</a>用包络读出 \\(z(w,q)=\\nabla_w c\\) 与无条件的 \\(z(p,w)=-\\nabla_w\\pi\\)。本课不重证两条引理。缺口是把二者的差别写成可调用的语言：后课劳动市场、税收归宿若把「要素需求」画成一条，会漏掉 \\(q\\) 随 \\(p\\) 动的那一层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>条件要素需求 \\(z(w,q)\\) 回答：产出锁在 \\(q\\) 时，要素价格变，厂商沿等产量如何换投入。它是成本最小化的解，齐次零次于 \\(w\\)，对 \\(q\\) 在一次齐次技术上线性。无条件要素需求 \\(z(p,w)\\) 回答：产品价格也给定、产量已经按利润最大调过之后，要素用多少。缺口是恒等式</p><p><span class="marginnote">术语翻译：「条件」指把产量 \\(q\\) 当成给定的约束条件，不是统计里的条件期望。\\(z(w,q)\\) 回答的是「必须生产 \\(q\\) 这么多时，每种要素买多少才最省钱」；「无条件」则是连 \\(q\\) 也让厂商自己挑。</span></p> \\[z_j(p,w)=z_j\\bigl(w,q(p,w)\\bigr), \\]<p>从而对 \\(w_k\\) 的导数多出一项产出效应：\\(\\partial z_j/\\partial q\\cdot\\partial q/\\partial w_k\\)。Shephard 只看见第一项（替代）；Hotelling 看见两项之和。把条件劳动需求直接贴到劳动市场上，等于假定产品市场的 \\(q\\) 冻住——短长期课有时故意这样做，但必须声明。</p><h3 id="替代矩阵不是要素市场的斜率" tabindex="-1">替代矩阵不是要素市场的斜率 <a class="header-anchor" href="#替代矩阵不是要素市场的斜率" aria-label="Permalink to &quot;替代矩阵不是要素市场的斜率&quot;">​</a></h3><p>\\(c\\) 对 \\(w\\) 凹，故 \\(D_w z(w,q)\\) 半负定、对称（可微时）。这是沿等产量的替代，类似希克斯需求。无条件需求对 \\(w\\) 的斜率还含 \\(q\\) 的调整，符号仍通常为负（要素作为利润问题里的「劣」价格），但弹性更大。不要把 Allen–Uzawa 替代弹性写成劳动需求的市场弹性。</p><p><span class="marginnote">消费者斯勒茨基：马歇尔 = 希克斯 + 财富项。厂商这里：无条件 = 条件 + 产出项。财富与产出不是同一通道，只是对偶平行。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定 \\(w,q\\)，用 Shephard 或等产量切点算 \\(z(w,q)\\)。给定 \\(p,w\\)，先由 \\(p=\\mathrm{MC}(q)\\) 解出 \\(q(p,w)\\)（下一课把这条供给写全），再代入条件需求。比较两条曲线：条件曲线沿等产量，无条件曲线沿扩张路径加上等产量滑动。</p><p>位似或一次齐次时，扩张路径是射线，\\(z(w,q)=q\\,a(w)\\)，产出效应与规模成比例。里昂惕夫没有替代，条件需求对 \\(w\\) 无弹性，无条件弹性全部来自 \\(q\\)。本课只标明分解，不估数字。</p>',14)),(l(),n(p,null,{default:e(()=>[o(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20SH%5B%22Shephard%EF%BC%9Az(w%2Cq)%22%5D%20--%3E%20COND%5B%22%E7%AD%89%E4%BA%A7%E9%87%8F%E4%B8%8A%E7%9A%84%E6%9B%BF%E4%BB%A3%22%5D%0A%20%20HOT%5B%22Hotelling%EF%BC%9Az(p%2Cw)%22%5D%20--%3E%20UNC%5B%22%E6%9B%BF%E4%BB%A3%20%2B%20%E4%BA%A7%E5%87%BA%E6%95%88%E5%BA%94%22%5D%0A%20%20COND%20--%3E%20ID%5B%22z(p%2Cw)%3Dz(w%2C%20q(p%2Cw))%22%5D%0A%20%20UNC%20--%3E%20ID%0A%20%20ID%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%94%A8%20%CF%80%20%E6%8A%8A%20q%20%E5%86%85%E7%94%9F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"本课 \\(p\\) 仍是参数。要素市场出清、买方垄断不在这里。也不把 \\(z\\) 写成限价簿上愿意成交的库存。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"产出效应的机制：\\(w_k\\) 上升 → 边际成本上升 → 最优 \\(q\\) 下降 → 所有正常要素少用。即使某种要素与 \\(k\\) 在等产量上是互补还是替代，这一层通常同向减少投入。条件需求把这层关掉，于是只剩「贵的要素被便宜的要素替换」，可能出现交叉价格为正（替代）。无条件交叉价格还要叠加规模收缩，净效应不定。",-1)),(l(),n(p,null,{default:e(()=>[o(i,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20WK%5B%22%E8%A6%81%E7%B4%A0%20k%20%E7%9A%84%E5%B7%A5%E8%B5%84%20w(k)%20%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20MC%5B%22%E8%BE%B9%E9%99%85%E6%88%90%E6%9C%AC%E4%B8%8A%E5%8D%87%22%5D%0A%20%20MC%20--%3E%20Q%5B%22%E6%9C%80%E4%BC%98%E4%BA%A7%E9%87%8F%20q%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20Q%20--%3E%20SCALE%5B%22%E4%BA%A7%E5%87%BA%E6%95%88%E5%BA%94%EF%BC%9A%E6%89%80%E6%9C%89%E6%AD%A3%E5%B8%B8%E8%A6%81%E7%B4%A0%E4%B8%80%E8%B5%B7%E5%B0%91%E7%94%A8%22%5D%0A%20%20WK%20--%3E%20SUB%5B%22%E6%9B%BF%E4%BB%A3%E6%95%88%E5%BA%94%EF%BC%9A%E8%B4%B5%E7%9A%84%20k%20%E8%A2%AB%E4%BE%BF%E5%AE%9C%E8%A6%81%E7%B4%A0%E6%9B%BF%E6%8D%A2%22%5D%0A%20%20SUB%20--%3E%20NET%5B%22%E6%97%A0%E6%9D%A1%E4%BB%B6%E9%9C%80%E6%B1%82%E5%8F%98%E5%8C%96%20%3D%20%E6%9B%BF%E4%BB%A3%20%2B%20%E4%BA%A7%E5%87%BA%22%5D%0A%20%20SCALE%20--%3E%20NET%0A%20%20COND%5B%22%E9%94%81%E4%BD%8F%20q%20%E7%9A%84%E6%9D%A1%E4%BB%B6%E9%9C%80%E6%B1%82%EF%BC%9A%E5%8F%AA%E5%89%A9%E6%9B%BF%E4%BB%A3%22%5D%20--%3E%20NET%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">数字实例：设工资从 10 涨到 11，边际成本上升使最优产量从 100 降到 90。即使劳动与资本完全不可替代（里昂惕夫技术），劳动用量也会随 \\(q\\) 缩到九成——这是产出效应；「改用资本替劳动」的替代效应则一点都没有。两条通道务必分开算。</span></p><p>与成本课的接口：上一课已经警告不要把 \\(z(w,q)\\) 当成要素市场反函数。本课给出正确的叠法。与利润课的接口：Hotelling 的 \\(-\\partial\\pi/\\partial w\\) 自动含两层；若实证只观察到 \\(q\\) 与 \\(z\\)，要用条件还是无条件，取决于数据里 \\(q\\) 是否被控制。</p><p><span class="marginnote">常见误区：初学者容易把条件要素需求曲线直接贴到劳动市场上当需求曲线用。实际上市场均衡里厂商可以调整产量，对应的应是无条件需求——它的弹性更大，因为它多含一层「产量收缩」。只有当 \\(q\\) 真被外生锁住（如配额）时，条件曲线才是对的。</span></p><p><span class="marginnote">短长期：资本沉没时，条件需求里一部分 \\(z\\) 不再对当期 \\(w\\) 反应，那是下一课之后的对象。本课默认全部投入可按 \\(w\\) 重选。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>联合生产、\\(q\\) 为向量时，产出效应是一条链 \\(\\partial z/\\partial q\\cdot\\partial q/\\partial w\\)。配额使 \\(q\\) 外生，无条件退化成条件——管制产业常用这一刀。IRS 下 \\(q(p,w)\\) 可以没有有限解，无条件需求整段不好定义；条件需求在给定 \\(q\\) 上仍可写。</p><p>也不处理要素质量、效率单位。本课 \\(z\\) 是物理投入。量化栏的成交量不是条件需求：这里没有报价，只有计划投入。</p><p>后课默认：写要素需求必须声明锁不锁 \\(q\\)；锁住的是 \\(z(w,q)\\)，放开的是 \\(z(p,w)\\)，二者差产出效应。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(z(w,q)\\) 沿等产量；\\(z(p,w)\\) 等于把最优 \\(q\\) 代回条件需求。</li><li>无条件斜率 = 替代（Shephard）+ 产出效应；市场弹性常用后者。</li><li>一次齐次时条件需求对 \\(q\\) 线性，产出效应成比例。</li><li>下一课把 \\(q\\) 放开，用利润最大写出供给。</li><li>出处：Varian, <em>Microeconomic Analysis</em>；Shephard, 1953；Hotelling, <em>JPE</em>, 1932。</li></ul>',10))])}const f=B(d,[["render",q]]);export{_ as __pageData,f as default};
